<?php
namespace App\Http\Controllers;
use App\Models\GuestBookLocation;use App\Models\GuestVisit;use App\Models\User;use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;use Maatwebsite\Excel\Concerns\FromArray;use Maatwebsite\Excel\Facades\Excel;use Mpdf\QrCode\Output\Png;use Mpdf\QrCode\QrCode;
class GuestBookController extends Controller {private function guard():void{abort_unless(in_array(Auth::user()->role,['superadmin','resepsionis'],true),403);}public function index(Request $request){$this->guard();$filters=$request->validate(['q'=>'nullable|string|max:255','date'=>'nullable|date','status'=>'nullable|in:inside,out']);$query=GuestVisit::with('location')->when($filters['q']??null,fn($q,$v)=>$q->where(fn($x)=>$x->where('name','like','%'.$v.'%')->orWhere('institution','like','%'.$v.'%')->orWhere('purpose','like','%'.$v.'%')->orWhere('visit_code','like','%'.$v.'%')))->when($filters['date']??null,fn($q,$v)=>$q->whereDate('checked_in_at',$v))->when(($filters['status']??null)==='inside',fn($q)=>$q->whereNull('checked_out_at'))->when(($filters['status']??null)==='out',fn($q)=>$q->whereNotNull('checked_out_at'));$visits=(clone $query)->latest('checked_in_at')->paginate(20)->withQueryString();$today=GuestVisit::whereDate('checked_in_at',today());$stats=['today'=>(clone $today)->count(),'inside'=>GuestVisit::whereNull('checked_out_at')->count(),'out'=>(clone $today)->whereNotNull('checked_out_at')->count(),'institutions'=>(clone $today)->distinct('institution')->count('institution')];$targetBidangOptions=UserController::$listBidang;$activeVisitors=GuestVisit::with('location')->whereNull('checked_out_at')->oldest('checked_in_at')->get();$locations=GuestBookLocation::withCount(['visits','visits as active_visits_count'=>fn($q)=>$q->whereNull('checked_out_at')])->latest()->get();return view('guest-book.index',compact('visits','stats','locations','targetBidangOptions','activeVisitors'));}public function storeLocation(Request $request){$this->super();$data=$request->validate(['name'=>'required|string|max:255']);GuestBookLocation::create($data+['public_token'=>(string)Str::uuid(),'created_by'=>Auth::id(),'is_active'=>true]);return back()->with('success','Lokasi buku tamu berhasil dibuat.');}public function toggleLocation(GuestBookLocation $location){$this->super();$location->update(['is_active'=>!$location->is_active]);return back()->with('success','Status link publik berhasil diperbarui.');}public function updateTargetBidang(Request $request,GuestVisit $visit){$this->guard();$data=$request->validate(['target_bidang'=>['required',\Illuminate\Validation\Rule::in(UserController::$listBidang)]]);$visit->update($data);return back()->with('success','Bidang tujuan tamu berhasil disimpan.');}public function checkout(GuestVisit $visit){$this->guard();if(!$visit->checked_out_at)$visit->update(['checked_out_at'=>now()]);return back()->with('success',$visit->name.' telah ditandai keluar.');}public function qr(GuestBookLocation $location){$this->guard();$png=(new Png())->output(new QrCode($location->public_url),700);return response($png,200,['Content-Type'=>'image/png','Content-Disposition'=>'attachment; filename="qr-buku-tamu-'.Str::slug($location->name).'.png"']);}public function exportExcel(Request $request){$this->guard();$rows=$this->exportRows($request);$export=new class($rows) implements FromArray{public function __construct(private array $rows){}public function array():array{return $this->rows;}};return Excel::download($export,'buku-tamu-'.now()->format('Ymd').'.xlsx');}public function exportPdf(Request $request){$this->guard();$visits=$this->filtered($request)->with('location')->oldest('checked_in_at')->get();return Pdf::loadView('guest-book.pdf',compact('visits'))->setPaper('a4','landscape')->download('buku-tamu-'.now()->format('Ymd').'.pdf');}public function accounts(Request $request){$this->super();$accounts=User::where('role','resepsionis')->when($request->q,fn($q,$v)=>$q->where(fn($x)=>$x->where('name','like','%'.$v.'%')->orWhere('username','like','%'.$v.'%')))->paginate(15)->withQueryString();return view('guest-book.accounts',compact('accounts'));}public function storeAccount(Request $request){$this->super();$d=$request->validate(['name'=>'required|string|max:255','username'=>'required|string|max:255|unique:users,username','whatsapp'=>'required|numeric','password'=>'required|string|min:8|confirmed']);$d['password']=Hash::make($d['password']);$d['role']='resepsionis';$d['user_type_status']='approved';User::create($d);return back()->with('success','Akun Pengelola Buku Tamu berhasil dibuat.');}public function resetAccount(Request $request,User $user){$this->super();abort_unless($user->role==='resepsionis',403);$d=$request->validate(['password'=>'required|string|min:8|confirmed']);$user->update(['password'=>Hash::make($d['password'])]);return back()->with('success','Password berhasil diperbarui.');}private function filtered(Request $r){return GuestVisit::query()->when($r->q,fn($q,$v)=>$q->where(fn($x)=>$x->where('name','like','%'.$v.'%')->orWhere('institution','like','%'.$v.'%')->orWhere('purpose','like','%'.$v.'%')))->when($r->date,fn($q,$v)=>$q->whereDate('checked_in_at',$v))->when($r->status==='inside',fn($q)=>$q->whereNull('checked_out_at'))->when($r->status==='out',fn($q)=>$q->whereNotNull('checked_out_at'));}private function exportRows(Request $r):array{$rows=[['Kode','Nama','Jabatan','Instansi','Keperluan & Tujuan','Bidang Tujuan','No. WhatsApp','Lokasi','Waktu Datang','Waktu Keluar','Status']];foreach($this->filtered($r)->with('location')->oldest('checked_in_at')->get() as $v)$rows[]=[ $v->visit_code,$v->name,$v->position?:'-',$v->institution,$v->purpose,$v->target_bidang?:'-',$v->whatsapp,$v->location?->name,$v->checked_in_at?->format('d-m-Y H:i'),$v->checked_out_at?->format('d-m-Y H:i')?:'-',$v->checked_out_at?'Keluar':'Sedang berkunjung'];return $rows;}private function super():void{abort_unless(Auth::user()->role==='superadmin',403);}}